ROOT.scriptdef:
SET NOCOUNT ON

DECLARE  @Bank_Kod VARCHAR(20),@Bank_Nazwa VARCHAR(100), @Bank_Id int, @BnD_Id int;

DECLARE bank_kursor CURSOR FOR 
SELECT distinct Bnk_Kod, Bnk_Nazwa, Bnk_GIDNumer FROM CDN.BankiFormKryt join cdn.Banki on BFK_BankDoUsuniecia = Bnk_GIDNumer FOR UPDATE OF BFK_BankDefId, Bnk_BnDId;
OPEN bank_kursor
FETCH NEXT FROM bank_kursor INTO @Bank_Kod ,@Bank_Nazwa,@Bank_Id ;


WHILE @@FETCH_STATUS = 0
BEGIN
	INSERT INTO cdn.BankiDefinicje (BND_Kod,BnD_Nazwa) VALUES(@Bank_Kod,@Bank_Nazwa) 
	IF @@ROWCOUNT > 0 
	BEGIN
		set @BnD_Id = SCOPE_IDENTITY();

		UPDATE CDN.BankiFormKryt 
		SET BFK_BankDefId = @BnD_Id
		WHERE BFK_BankDoUsuniecia = @Bank_Id

		UPDATE CDN.Banki
		SET Bnk_BnDId = @BnD_Id
		WHERE Bnk_GIDNumer = @Bank_Id

	END
	FETCH NEXT FROM bank_kursor INTO @Bank_Kod ,@Bank_Nazwa,@Bank_Id ;
END

CLOSE bank_kursor;
DEALLOCATE bank_kursor; 

ALTER TABLE cdn.BankiFormKryt
DROP COLUMN BFK_BankDoUsuniecia;

	

SET NOCOUNT OFF
